use vstd::prelude::*;

verus! {

fn intersperse(numbers: &[i32], delim: i32) -> (res: Vec<i32>)
    ensures
        res@.len()
            == if numbers@.len() == 0 {
                0
            } else {
                2 * numbers@.len() - 1
            },
        forall|k: int|
            0 <= k < numbers@.len() ==>
                res@[2 * k] == numbers@[k],
        forall|k: int|
            0 <= k < numbers@.len() - 1 ==>
                res@[2 * k + 1] == delim,
        numbers@.len() > 0 ==> res@[res@.len() - 1] == numbers@[numbers@.len() - 1],
{
    let mut res: Vec<i32> = Vec::new();

    let n = numbers.len();
    if n == 0 {
        return res;
    }

    let mut i: usize = 0;
    while i < n
        invariant
            i <= n,
            // length is 2*i if we haven't added the delimiter after i-1 yet (i==n handled)
            res@.len() == 2 * (i as int) - if i == 0 { 0 } else { 1 },
            // even positions correspond to numbers[0..i)
            forall|k: int| 0 <= k < i as int ==> res@[2 * k] == numbers@[k],
            // odd positions up to i-1 are delimiters
            forall|k: int| 0 <= k < (i as int) - 1 ==> res@[2 * k + 1] == delim,
    {
        // push the next number
        res.push(numbers[i]);

        // if not the last element, push delimiter
        if i + 1 < n {
            res.push(delim);
        }

        i += 1;
    }

    res
}

} // verus!